parameters.jsonBody:
={
  "model": "claude-haiku-4-5-20251001",
  "max_tokens": 700,
  "system": "Tu es un assistant de tri d'emails pour DB Industrie (distribution de pieces industrielles). Tu analyses un email recu et tu le classes. Reponds UNIQUEMENT en JSON valide, sans texte ni balises markdown. Schema: {\"categorie\":\"demande_produit|statut_commande|livraison|newsletter_pub|interne|autre\",\"specificite\":\"precise|vague\",\"produits\":[{\"ref_demandee\":\"string ou null\",\"designation\":\"string\",\"marque\":\"string ou null\",\"quantite\":\"number ou null\",\"mots_cles\":[\"string\"]}],\"resume\":\"string\"}. REGLES DE CLASSEMENT: 'demande_produit' = un client externe demande a acheter/chiffrer un produit, demande un prix, un devis, une disponibilite a l'achat. C'est la SEULE categorie qui sera traitee. 'statut_commande' = question sur une commande deja passee (ou en est ma commande). 'livraison' = question sur date/suivi de livraison. 'newsletter_pub' = publicite, newsletter, promo, demande d'avis, panier abandonne. 'interne' = mail entre collegues, RH, organisation, question interne. 'autre' = tout le reste. IMPORTANT - MAILS TRANSFERES: si le mail est un transfert (Fwd:, TR:, 'Forwarded message', en-tetes 'De:/Envoye:/A:'), IGNORE l'enrobage de transfert et classe selon la DEMANDE D'ORIGINE contenue dans le corps. Un mail transfere en interne contenant une demande produit d'un client (ex: 'points d'ancrage pour IPN', 'roulement', 'piece X') doit etre classe 'demande_produit'. En cas de doute entre demande_produit et autre chose, ne choisis demande_produit QUE si une demande de produit/piece/reference est identifiable dans le corps. Pour 'specificite' (seulement si demande_produit): 'precise' si reference/marque/modele exact cite (le client veut CE produit), 'vague' si demande generique acceptant plusieurs options. Si categorie != demande_produit, mets produits=[] et specificite=null.",
  "messages": [
    { "role": "user", "content": {{ JSON.stringify('Expediteur: ' + ($json.from || $json.fromEmail || 'inconnu') + '\nObjet: ' + ($json.subject || '') + '\n\n' + ($json.textPlain || $json.text || '')) }} }
  ]
}

parameters.jsCode:
// Traite TOUS les items du lot (1 item = 1 mail). pairedItem conserve le lien
// vers le mail d'origine pour itemMatching en aval.
const items = $input.all();
const produits = ($('Charger produits (embarque)').first().json.produits) || [];
const norm = s => (s || '').toString().toLowerCase().replace(/[\s\-_.]/g, '');
const tokens = s => (s || '').toString().toLowerCase().split(/[^a-z0-9]+/).filter(t => t.length > 1);
function scorer(demande, prod) {
  let score = 0;
  const refD = norm(demande.ref_demandee);
  const refP = norm(prod.ref_constructeur);
  if (refD && refP) {
    if (refP === refD) score += 100;
    else if (refP.includes(refD) || refD.includes(refP)) score += 60;
  }
  const kw = [...(demande.mots_cles || []), ...tokens(demande.designation)];
  const desP = (prod.designation || '').toLowerCase();
  kw.forEach(k => { if (desP.includes(k.toLowerCase())) score += 8; });
  if (demande.marque && norm(demande.marque) && desP.includes(demande.marque.toLowerCase())) score += 10;
  return score;
}

const out = [];
for (let i = 0; i < items.length; i++) {
  const resp = items[i].json;
  let parsed;
  try {
    const txt = resp.content.filter(c => c.type === 'text').map(c => c.text).join('');
    parsed = JSON.parse(txt.replace(/```json|```/g, '').trim());
  } catch (e) {
    out.push({ json: { erreur: 'Parsing Claude impossible', brut: resp, trouve_catalogue: false, confiance: 'aucun', specificite: 'vague', resultats: [] }, pairedItem: { item: i } });
    continue;
  }
  const resultats = (parsed.produits || []).map(demande => {
    const classes = produits
      .map(p => ({ id_ebp: p.id_ebp, ref_constructeur: p.ref_constructeur, designation: p.designation, prix_vente_ht: p.prix_vente_ht, _score: scorer(demande, p) }))
      .filter(p => p._score >= 24)
      .sort((a, b) => b._score - a._score)
      .slice(0, 5);
    return { demande, candidats: classes };
  });
  const meilleurScore = Math.max(0, ...resultats.flatMap(r => r.candidats.map(c => c._score)));
  // 3 niveaux: fort (>=60 match ref) -> catalogue seul ; douteux (32-59) -> web + pistes catalogue ; rien (<32) -> web pur
  let confiance;
  if (meilleurScore >= 60) confiance = 'fort';
  else if (meilleurScore >= 32) confiance = 'douteux';
  else confiance = 'aucun';
  const trouve_catalogue = (confiance === 'fort');
  const exp = $('Normaliser mail').itemMatching(i).json;
  const expediteur = exp.from || exp.fromEmail || 'inconnu';
  out.push({ json: { intention: parsed.intention, specificite: parsed.specificite || 'vague', resume: parsed.resume, resultats, trouve_catalogue, confiance, meilleurScore, expediteur }, pairedItem: { item: i } });
}
return out;

function cleanMarkdown(t){
  if(!t) return '';
  let s = t;
  // Tableaux markdown: convertir chaque ligne |a|b|c| en 'a - b - c', supprimer lignes de separation |---|
  s = s.split('\n').map(line => {
    const l = line.trim();
    if(/^\|?[\s:|-]+\|?$/.test(l) && l.includes('-')) return '';  // ligne separatrice |---|---|
    if(l.startsWith('|') && l.endsWith('|')){
      const cells = l.slice(1,-1).split('|').map(c=>c.trim()).filter(c=>c.length);
      return cells.join(' - ');
    }
    return line;
  }).join('\n');
  // Liens markdown [texte](url) -> texte: url
  s = s.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '$1 : $2');
  // Gras/italique **x** *x* __x__ -> x
  s = s.replace(/\*\*([^*]+)\*\*/g, '$1').replace(/\*([^*]+)\*/g, '$1').replace(/__([^_]+)__/g, '$1');
  // Titres ## ### -> juste le texte
  s = s.replace(/^#{1,6}\s*/gm, '');
  // Citations > au debut de ligne
  s = s.replace(/^>\s?/gm, '');
  // Backticks
  s = s.replace(/`/g, '');
  // Lignes de tirets seules ---
  s = s.replace(/^\s*-{3,}\s*$/gm, '');
  // Emojis courants en debut de titre (optionnel: on enleve les pictos isoles)
  s = s.replace(/[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}]/gu, '');
  // Nettoyer triples sauts de ligne
  s = s.replace(/\n{3,}/g, '\n\n').trim();
  return s;
}
// Traite TOUS les items du lot ; itemMatching retrouve le mail d'origine de chaque item.
const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const resp = items[i].json;
  const texte = (resp.content || []).filter(c => c.type === 'text').map(c => c.text).join('');
  const corps = cleanMarkdown(texte);
  const mailOrig = $('Normaliser mail').itemMatching(i).json;
  out.push({ json: { sujet: 'PROPOSITION A VALIDER - ' + (mailOrig.subject || '(sans objet)'), corps, id_mail: mailOrig.id || '' }, pairedItem: { item: i } });
}
return out;

