  s = s.replace(/[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}]/gu, '');
  // Nettoyer triples sauts de ligne
  s = s.replace(/\n{3,}/g, '\n\n').trim();
  return s;
}
// Traite TOUS les items du lot ; itemMatching retrouve le mail d'origine de chaque item.
const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const resp = items[i].json;
  const texte = (resp.content || []).filter(c => c.type === 'text').map(c => c.text).join('');
  const corps = cleanMarkdown(texte);
  const mailOrig = $('Normaliser mail').itemMatching(i).json;
  out.push({ json: { sujet: 'PROPOSITION (recherche web) A VALIDER - ' + (mailOrig.subject || '(sans objet)'), corps, id_mail: mailOrig.id || '' }, pairedItem: { item: i } });
}
return out;

// Normalise TOUS les mails du poll (le trigger peut renvoyer plusieurs items d'un coup).
// Gere les transferts multipart imbriques. Retourne 1 item par mail.
const mails = $('Mail entrant (Gmail)').all();

function headersFind(obj, name){
  const targets = [];
  if (obj.payload && Array.isArray(obj.payload.headers)) targets.push(obj.payload.headers);
  if (Array.isArray(obj.headers)) targets.push(obj.headers);
  for (const arr of targets){
    const h = arr.find(x => (x.name||'').toLowerCase() === name.toLowerCase());
    if (h && h.value) return h.value;
  }
  return '';
}
function decodeB64url(s){ try { return Buffer.from((s||'').replace(/-/g,'+').replace(/_/g,'/'),'base64').toString('utf8'); } catch(e){ return ''; } }
function decodeEntities(s){ return (s||'').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&amp;/g,'&').replace(/&quot;/g,'\"').replace(/&#39;/g,"'").replace(/&nbsp;/g,' '); }
function stripHtml(h){ return decodeEntities((h||'').replace(/<style[^>]*>[\s\S]*?<\/style>/gi,' ').replace(/<[^>]+>/g,' ')).replace(/\s+/g,' ').trim(); }

// Parcours RECURSIF de toutes les parties, collecte text/plain et text/html
function collectBodies(part, acc){
  if (!part) return;
  if (Array.isArray(part.parts)) { part.parts.forEach(p => collectBodies(p, acc)); }
  if (part.mimeType === 'text/plain' && part.body && part.body.data) acc.plain.push(decodeB64url(part.body.data));
  if (part.mimeType === 'text/html' && part.body && part.body.data) acc.html.push(decodeB64url(part.body.data));
}

const out = [];
for (const m of mails) {
  const item = m.json;
  let from = '', subject = '', body = '';
  try {
    from = item.from || item.From || item.fromEmail || headersFind(item,'From');
    subject = item.subject || item.Subject || headersFind(item,'Subject');
    if (item.payload){
      const acc = { plain: [], html: [] };
      collectBodies(item.payload, acc);
      if (!acc.plain.length && !acc.html.length && item.payload.body && item.payload.body.data){
        acc.plain.push(decodeB64url(item.payload.body.data));
      }
      if (acc.plain.length) body = decodeEntities(acc.plain.join('\n'));
      else if (acc.html.length) body = stripHtml(acc.html.join('\n'));
    }
    if (!body) body = decodeEntities(item.textPlain || item.text || '');
    if (body && /<[a-z][\s\S]*>/i.test(body)) body = stripHtml(body);
    if (!body) body = decodeEntities(item.snippet || '');
  } catch (e) {
    // Un mail illisible ne doit pas faire perdre les autres mails du lot
    body = decodeEntities(item.snippet || '');
  }
  out.push({ json: {
    id: item.id || '',
    threadId: item.threadId || '',
    from: from || 'inconnu',
    subject: subject || '(sans objet)',
    textPlain: body
  } });
}
return out;
